public class HttpForm{}public class ResultData{public bool Succeed{get{return true;}}public string Error{get{return null;}}}public class FormManager{public static FormManager GetInstance(){return null;}public object Push(object form){return null;}}public static class SubForm{public static object MakeDialog(string text){return null;}}public static class Language{public static bool SetLanguagePack(string s,byte[] data,bool enabled=true){return true;}}public class LanguageForm{public int mode_;public static string langDownloadUrl_;public byte[] langDownloadData_;public static System.Threading.ThreadStart callback_;public System.Action<HttpForm,ResultData> Make(){return delegate(HttpForm form,ResultData data){if(data.Succeed){bool testedValue=Language.SetLanguagePack(langDownloadUrl_,langDownloadData_);if(testedValue&&callback_!=null){callback_();}}else{FormManager instance=FormManager.GetInstance();LanguageForm nextLanguageForm = new LanguageForm();
